<script lang="ts">
import PublisherRecovery from '../components/PublisherRecovery.svelte';
import RemotePublisher from '../components/RemotePublisher.svelte';
import {onMount} from 'svelte';
import {invoke} from '@tauri-apps/api/core';
import type {AdManifest} from '../generated/AdManifest';
import type {AdSlot} from '../generated/AdSlot';
import type {AdChannel} from '../generated/AdChannel';
import type {Campaign} from '../generated/Campaign';
import type {ImportedImage} from '../generated/ImportedImage';
import type {OperationOutcome} from '../generated/OperationOutcome';
import type {PublisherView} from '../generated/PublisherView';
import type {PublisherCleanupPreview} from '../generated/PublisherCleanupPreview';
import type {PublisherGcPreview} from '../generated/PublisherGcPreview';
import AdCard from '../components/AdCard.svelte';
import Icon from '../components/Icon.svelte';
import {slots,slotNames,dateTime,hostLabel,dialogFocus,errorMessage} from '../ui';
import {dateInput,parseDate,systemTimeZone} from '../operations-date';
let {fixture=false,onoutcome}:{fixture?:boolean;onoutcome:(result:OperationOutcome)=>void}=$props();
let draft=$state<AdManifest|null>(null),publisher=$state<PublisherView|null>(null);
let selected=$state<AdSlot>('residential_broadband'),period=$state(0),busy=$state(''),error=$state(''),loading=$state(true),dirty=$state(false),zone=$state('local'),previewPeriod=$state(0),previewSize=$state('1180'),images=$state<Record<string,string>>({}),publishChannel=$state<AdChannel|null>(null),passphrase=$state('');
let recoveryHolding=$state(false);
let backupOutcome=$state<OperationOutcome|null>(null),backupError=$state('');
let retain=$state(128),releaseResolution=$state(false),cleanupPreview=$state<PublisherCleanupPreview|null>(null),gcPreview=$state<PublisherGcPreview|null>(null),maintenanceOutcome=$state<OperationOutcome|null>(null);
let localZone=$state(systemTimeZone());
const editingZone=$derived(zone==='utc'?'UTC':localZone);
function refreshLocalZone(){const current=systemTimeZone();if(current!==localZone)localZone=current;}
const content=$derived(draft?.slots.find(s=>s.slot===selected)??null);
const campaign=$derived(content?.campaigns[period]??null);
const validation=$derived(validate(draft));
function blank():AdManifest{const now=Math.floor(Date.now()/1000);return{schema_version:1,channel:'preview',content_revision:1,key_id:'待配置',issued_at:now,expires_at:now+86400*30,release_id:crypto.randomUUID(),slots:slots.map(slot=>({slot,enabled:false,campaigns:[]}))};}
function validate(d:AdManifest|null):string[]{if(!d)return['草稿尚未读取'];const errors:string[]=[];for(const s of d.slots){for(const c of s.campaigns){if(!c.title.trim()||!c.description.trim()||!c.merchant_id.trim()||!c.merchant_name.trim()||!c.button_text.trim())errors.push(`${slotNames[s.slot]}：请填写商家、标题、说明和按钮`);try{const u=new URL(c.target_url);if(u.protocol!=='https:'||u.username||u.password||(u.port&&u.port!=='443'))throw Error();}catch{errors.push(`${slotNames[s.slot]}：需要有效的 HTTPS 商家地址`);}if(!c.image.sha256||!c.image.bytes)errors.push(`${slotNames[s.slot]}：请导入静态图片`);if(c.ends_at<=c.starts_at)errors.push(`${slotNames[s.slot]}：结束应晚于开始`);}const[a,b]=s.campaigns;if(a&&b&&a.enabled&&b.enabled&&a.starts_at<b.ends_at&&b.starts_at<a.ends_at)errors.push(`${slotNames[s.slot]}：两期时间重叠`);}return[...new Set(errors)];}
function edit(field:keyof Campaign,value:string|number|boolean){if(!draft)return;const d=structuredClone($state.snapshot(draft)),c=d.slots.find(s=>s.slot===selected)?.campaigns[period];if(c){Object.assign(c,{[field]:value});draft=d;dirty=true;}}
function toggleSlot(enabled:boolean){if(!draft)return;const d=structuredClone($state.snapshot(draft)),s=d.slots.find(s=>s.slot===selected);if(s){s.enabled=enabled;draft=d;dirty=true;}}
function add(){if(!draft||!content||content.campaigns.length>=2)return;const d=structuredClone($state.snapshot(draft)),s=d.slots.find(s=>s.slot===selected)!;const start=Math.max(Math.floor(Date.now()/1000),s.campaigns[0]?.ends_at??0);s.campaigns.push({campaign_id:crypto.randomUUID(),merchant_id:'',merchant_name:'',title:'',description:'',image:{sha256:'',mime:'image/png',bytes:0,width:0,height:0},button_text:'了解详情',target_url:'',starts_at:start,ends_at:start+86400*7,enabled:true});draft=d;period=s.campaigns.length-1;dirty=true;}
function remove(){if(!draft)return;const d=structuredClone($state.snapshot(draft));d.slots.find(s=>s.slot===selected)?.campaigns.splice(period,1);draft=d;period=0;dirty=true;}
function editDate(field:'starts_at'|'ends_at',input:HTMLInputElement){const renderedZone=input.dataset.timezone??'';const result=parseDate(input.value,renderedZone,input.dataset.utc==='true');if(result.status==='zone_changed'){refreshLocalZone();error='系统时区已变化，已刷新编辑时区。此次时间修改未保存，请重新输入。';return;}if(result.status==='invalid'){error='请输入有效的开始或结束时间。';return;}edit(field,result.value);}
async function reloadPublisher(){if(fixture)return;[draft,publisher]=await Promise.all([invoke<AdManifest>('ad_draft_read'),invoke<PublisherView>('publisher_status')]);dirty=false;await previews();}
async function previews(){if(!draft||fixture)return;for(const s of draft.slots)for(const c of s.campaigns)if(c.image.sha256&&!images[c.image.sha256]){try{images={...images,[c.image.sha256]:await invoke<string>('ad_image_preview',{sha256:c.image.sha256})};}catch{/* Display missing-image state without inventing success. */}}}
async function save(){if(!draft||busy)return;if(fixture){dirty=false;onoutcome({completed:false,message:'合成草稿仅保留在当前预览，未写入真实资料。',recovery:null});return;}busy='正在保存本地草稿…';error='';try{draft=await invoke<AdManifest>('ad_draft_save',{manifest:$state.snapshot(draft)});dirty=false;onoutcome({completed:true,message:'草稿已保存到本机，尚未发布。',recovery:null});}catch(e){error=errorMessage(e);}finally{busy='';}}
async function imageInput(e:Event){const input=e.currentTarget as HTMLInputElement,file=input.files?.[0];if(!file||!campaign)return;if(file.size>1024*1024){error='原始图片超过 1 MiB，请选择较小的 PNG/JPEG。';input.value='';return;}busy='正在解码、归一化并校验素材…';error='';try{if(fixture){onoutcome({completed:false,message:'合成预览不导入真实素材，请在 Personal App 中操作。',recovery:null});return;}const result=await invoke<ImportedImage>('import_ad_image',{bytes:Array.from(new Uint8Array(await file.arrayBuffer()))});images={...images,[result.asset.sha256]:result.preview_data_url};if(draft){const d=structuredClone($state.snapshot(draft)),c=d.slots.find(s=>s.slot===selected)?.campaigns[period];if(c){c.image=result.asset;draft=d;dirty=true;}}}catch(e){error=errorMessage(e);}finally{busy='';input.value='';}}
async function publish(channel:AdChannel){publishChannel=null;if(busy||!draft)return;if(fixture){onoutcome({completed:false,message:'合成预览不写入本机发布目录，也不执行真实发布。',recovery:null});return;}busy=`正在签名、提交并回读${channel==='preview'?'预览':'正式'}渠道内容…`;error='';try{onoutcome(await invoke<OperationOutcome>('publish_ad',{channel}));publisher=await invoke<PublisherView>('publisher_status');}catch(e){error=errorMessage(e);}finally{busy='';}}
async function pause(slot:AdSlot|null){if(busy)return;if(fixture){onoutcome({completed:false,message:'合成预览不发布暂停版本。',recovery:null});return;}busy='正在建立更高序号的暂停草稿…';error='';try{draft=await invoke<AdManifest>('pause_ad',{slot});dirty=false;onoutcome({completed:true,message:'暂停草稿已创建，请预览后发布到正式渠道。',recovery:null});}catch(e){error=errorMessage(e);}finally{busy='';}}
async function restore(releaseId:string){if(busy)return;busy='正在读取历史并建立更高序号草稿…';error='';try{draft=await invoke<AdManifest>('restore_ad_history',{releaseId});dirty=false;await previews();}catch(e){error=errorMessage(e);}finally{busy='';}}
async function publisherAction(command:string,label:string,backupCard=false){if(busy||fixture)return;if(backupCard){backupOutcome=null;backupError='';}busy=label;error='';try{const result=await invoke<OperationOutcome>(command);if(backupCard)backupOutcome=result;onoutcome(result);publisher=await invoke<PublisherView>('publisher_status');}catch(e){error=errorMessage(e);if(backupCard)backupError=error;}finally{busy='';}}
async function backup(){if(busy||fixture)return;backupOutcome=null;backupError='';if(passphrase.length<12)return;busy='正在生成加密运营备份…';error='';try{backupOutcome=await invoke<OperationOutcome>('export_publisher_backup',{passphrase});onoutcome(backupOutcome);passphrase='';}catch(e){backupError=error=errorMessage(e);}finally{busy='';}}
async function restoreBackup(e:Event){const input=e.currentTarget as HTMLInputElement,file=input.files?.[0];if(!file||busy||fixture)return;backupOutcome=null;backupError='';if(file.size>64*1024*1024||passphrase.length<12){backupError=error='备份须不超过 64 MiB；请先输入至少 12 个字符的口令。';input.value='';return;}busy='正在解密并核对恢复前置条件…';error='';try{backupOutcome=await invoke<OperationOutcome>('restore_publisher_backup',{bytes:Array.from(new Uint8Array(await file.arrayBuffer())),passphrase});onoutcome(backupOutcome);passphrase='';draft=await invoke<AdManifest>('ad_draft_read');await previews();}catch(e){backupError=error=errorMessage(e);}finally{busy='';input.value='';}}
function clearMaintenance(){cleanupPreview=null;gcPreview=null;}
async function previewCleanup(){if(busy||fixture)return;clearMaintenance();maintenanceOutcome=null;error='';if(!Number.isInteger(retain)||retain<0||retain>256){error='保留历史条数须为 0 至 256 的整数。';return;}busy='正在核对本机历史与素材引用…';try{cleanupPreview=await invoke<PublisherCleanupPreview>('preview_publisher_cleanup',{retain,releaseResolution});}catch(e){error=errorMessage(e);}finally{busy='';}}
async function confirmCleanup(){const plan=cleanupPreview;if(busy||fixture||!plan||plan.pending_blocks_commit||plan.retain!==retain||plan.release_resolution!==releaseResolution)return;clearMaintenance();busy='正在提交已确认的索引整理…';error='';try{maintenanceOutcome=await invoke<OperationOutcome>('commit_publisher_cleanup',{digest:plan.digest,retain:plan.retain,releaseResolution:plan.release_resolution});onoutcome(maintenanceOutcome);publisher=await invoke<PublisherView>('publisher_status');}catch(e){error=errorMessage(e);}finally{busy='';}}
async function previewGc(){if(busy||fixture)return;clearMaintenance();maintenanceOutcome=null;busy='正在核对本批可回收文件…';error='';try{gcPreview=await invoke<PublisherGcPreview>('preview_publisher_gc');}catch(e){error=errorMessage(e);}finally{busy='';}}
async function confirmGc(){const plan=gcPreview;if(busy||fixture||!plan||plan.pending_blocks_commit)return;clearMaintenance();busy='正在回收已确认文件并结束本批…';error='';try{maintenanceOutcome=await invoke<OperationOutcome>('commit_publisher_gc',{digest:plan.digest});onoutcome(maintenanceOutcome);publisher=await invoke<PublisherView>('publisher_status');}catch(e){error=errorMessage(e);}finally{busy='';}}
onMount(()=>{refreshLocalZone();const timer=window.setInterval(refreshLocalZone,1000);window.addEventListener('focus',refreshLocalZone);document.addEventListener('visibilitychange',refreshLocalZone);return()=>{window.clearInterval(timer);window.removeEventListener('focus',refreshLocalZone);document.removeEventListener('visibilitychange',refreshLocalZone);};});
onMount(()=>{void(async()=>{if(fixture){draft=blank();publisher={source:'本机运营（合成预览）',status:'waiting',message:'合成界面不读取本机发布目录，也不创建真实签名密钥。',history:[]};return;}[draft,publisher]=await Promise.all([invoke<AdManifest>('ad_draft_read'),invoke<PublisherView>('publisher_status')]);await previews();})().catch(e=>error=errorMessage(e)).finally(()=>loading=false);});
</script>
{#if loading}<div class="notice" role="status"><span class="spinner"></span>正在读取本地草稿与发布历史…</div>{/if}
{#if busy}<div class="notice" role="status"><span class="spinner"></span>{busy}</div>{/if}
{#if error}<div class="notice danger" role="alert"><Icon name="alert"/><p>{error}</p></div>{/if}
<div class="notice"><Icon name="lock"/><div><strong>{publisher?.source??'本机广告运营'}</strong><p>{publisher?.message??'广告签名私钥和远程写入凭据保存在本机 Keychain。'}</p>{#if publisher?.status==='wait_signing_key'}<p>尚未初始化签名密钥。请先点击下方按钮，在本机 Keychain 创建广告签名密钥。</p>{/if}<button class="text-button" disabled={!!busy||recoveryHolding||fixture} onclick={()=>publisherAction('create_ad_signing_key','正在本机 Keychain 创建广告签名密钥…')}>创建本机广告签名密钥</button></div></div>
<PublisherRecovery {fixture} disabled={!!busy||dirty} onholding={holding=>recoveryHolding=holding} onchanged={reloadPublisher} {onoutcome}/>
<fieldset class="recovery-guard" disabled={recoveryHolding}>
<RemotePublisher {fixture} disabled={!!busy||recoveryHolding}/>
{#if draft}
<section class="panel"><div class="section-heading"><div><h2>本地草稿 <span class="badge">序号 {draft.content_revision}</span></h2><p>{dirty?'有未保存修改':'本地内容已读取'} · 日常商家更新沿用当前软件版本</p></div><button class="primary" disabled={!!busy} onclick={save}>保存草稿</button></div>
<div class="slot-tabs" role="tablist" aria-label="广告位">{#each slots as slot}<button role="tab" aria-selected={selected===slot} class:chosen={selected===slot} onclick={()=>{selected=slot;period=0;}}>{slotNames[slot]}</button>{/each}</div>
{#if content}<div class="editor-toolbar"><label class="checkbox-label"><input type="checkbox" checked={content.enabled} onchange={e=>toggleSlot(e.currentTarget.checked)}/>允许此广告位展示</label><div class="button-row"><button class="text-button" disabled={!!busy} onclick={()=>pause(selected)}>暂停此位</button><button class="text-button" disabled={!!busy} onclick={()=>pause(null)}>全部暂停</button></div></div>
<div class="period-toolbar"><div class="button-row">{#each content.campaigns as c,index}<button class="period-button" class:chosen={period===index} onclick={()=>period=index}>{index===0?'当前一期':'下一期'}</button>{/each}<button class="outline" disabled={content.campaigns.length>=2||!!busy} onclick={add}>＋ 添加一期</button></div><label class="timezone-label">编辑时区 <select bind:value={zone}><option value="local">{localZone}</option><option value="utc">UTC</option></select></label></div>
{#if campaign}<div class="editor-fields">
<label>商家名称<input maxlength="80" value={campaign.merchant_name} oninput={e=>edit('merchant_name',e.currentTarget.value)}/></label><label>商家标识<input maxlength="80" value={campaign.merchant_id} oninput={e=>edit('merchant_id',e.currentTarget.value)} placeholder="稳定的商家 ID"/></label>
<label class="wide">标题<input maxlength="120" value={campaign.title} oninput={e=>edit('title',e.currentTarget.value)}/></label><label class="wide">说明<textarea maxlength="500" rows="3" value={campaign.description} oninput={e=>edit('description',e.currentTarget.value)}></textarea></label>
<label>按钮文字<input maxlength="40" value={campaign.button_text} oninput={e=>edit('button_text',e.currentTarget.value)}/></label><label>商家 HTTPS 地址<input type="url" value={campaign.target_url} oninput={e=>edit('target_url',e.currentTarget.value)} placeholder="https://example.com/"/><small>规范化主机：{hostLabel(campaign.target_url)}</small></label>
{#key editingZone}<label>开始时间<input type="datetime-local" data-timezone={editingZone} data-utc={zone==='utc'} value={dateInput(campaign.starts_at,editingZone)} onchange={e=>editDate('starts_at',e.currentTarget)}/></label><label>结束时间<input type="datetime-local" data-timezone={editingZone} data-utc={zone==='utc'} value={dateInput(campaign.ends_at,editingZone)} onchange={e=>editDate('ends_at',e.currentTarget)}/></label>{/key}
<div class="wide image-row"><div><strong>静态 PNG / JPEG</strong><p>归一化后不超过 1 MiB、200 万像素。动画和格式混淆会被拒绝。</p>{#if campaign.image.bytes}<small>{campaign.image.width} × {campaign.image.height} · {Math.ceil(campaign.image.bytes/1024)} KiB</small>{/if}</div><label class="outline file-button">导入图片<input type="file" accept="image/png,image/jpeg" disabled={!!busy} onchange={imageInput}/></label></div>
<div class="wide editor-toolbar"><label class="checkbox-label"><input type="checkbox" checked={campaign.enabled} onchange={e=>edit('enabled',e.currentTarget.checked)}/>启用此期</label><button class="text-button remove" disabled={!!busy} onclick={remove}>移除此期草稿</button></div></div>
{:else}<div class="empty-state"><Icon name="image" size={30}/><h2>此广告位还没有排期</h2><p>每位可保存当前一期和下一期，三个广告位互不覆盖。</p><button class="outline" onclick={add}>添加第一期</button></div>{/if}{/if}</section>
<section class="panel"><div class="section-heading"><div><h2>本机草稿预览</h2><p>使用客户端共用广告卡片。此处展示草稿，不打开商家链接，也不代表已发布。</p></div><div class="button-row"><select aria-label="预览期次" bind:value={previewPeriod}><option value={0}>当前一期</option><option value={1}>下一期</option></select><select aria-label="预览窗口尺寸" bind:value={previewSize}><option value="1180">1180 × 800</option><option value="960">960 × 680</option></select></div></div><p class="preview-label">对应 {previewSize==='1180'?'1180 × 800':'960 × 680'} 窗口的卡片区域 · 随可用空间缩放</p><div class="preview-grid" class:compact={previewSize==='960'}>{#each slots as slot}{@const c=draft.slots.find(s=>s.slot===slot)}<AdCard {slot} campaign={c?.campaigns[previewPeriod]??null} enabled={c?.enabled??false} preview imageUrl={images[c?.campaigns[previewPeriod]?.image.sha256??'']??''}/>{/each}</div></section>
<section class="panel"><h2>本机签名发布与回读</h2><p class="muted">本机预览区与正式区使用独立目录。发布保存图片、签名和不可变版本，再核验回读结果。不向其他用户远程投放。</p>{#if validation.length}<div class="validation"><strong>发布前需要处理</strong><ul>{#each validation as item}<li>{item}</li>{/each}</ul></div>{/if}<div class="button-row"><button class="outline" disabled={!!busy||dirty||!!validation.length} onclick={()=>publishChannel='preview'}>发布到预览渠道</button><button class="primary" disabled={!!busy||dirty||!!validation.length} onclick={()=>publishChannel='production'}>发布到正式渠道</button></div><p class="muted footnote">预览发布仅供本机运营核对。正式发布供本机两个发行的广告区读取；请开启对应广告位并刷新广告内容。展示仍受签名、排期与缓存时限约束。</p></section>
{/if}
<section class="panel"><h2>本机发布历史与恢复</h2><p class="muted">恢复历史会建立更高内容序号。历史按下方整理设置保留。当前内容与仍被引用的素材受保护。</p>{#if publisher?.history.length}<div class="history-list">{#each publisher.history as r}<div><span><strong>序号 {r.revision} · {r.channel==='preview'?'本机预览':'本机正式'}</strong><small>{dateTime(r.published_at)} · {r.verified?'本机签名回读已验证':'本机回读待确认'}</small></span><button class="outline" disabled={!!busy} onclick={()=>restore(r.release_id)}>恢复为新草稿</button></div>{/each}</div>{:else}<p class="empty-copy">尚无已验证发布记录。</p>{/if}</section>
<section class="panel"><h2>本机历史与素材整理</h2><p class="muted">默认保留 128 条历史，包含本机预览和正式内容对应的现有记录。先确认索引整理，再单独预览和确认文件回收。</p><label class="backup-password">保留历史条数<input type="number" min="0" max="256" step="1" value={retain} disabled={!!busy||recoveryHolding||fixture} onchange={e=>{retain=e.currentTarget.valueAsNumber;clearMaintenance();}}/></label><label class="checkbox-label"><input type="checkbox" checked={releaseResolution} disabled={!!busy||recoveryHolding||fixture} onchange={e=>{releaseResolution=e.currentTarget.checked;clearMaintenance();}}/>释放上次未验证发布的处理记录槽</label><div class="button-row"><button class="outline" disabled={!!busy||recoveryHolding||fixture} onclick={previewCleanup}>预览索引整理</button><button class="text-button" disabled={!!busy||recoveryHolding||fixture} onclick={previewGc}>预览本批文件回收</button></div>
{#if cleanupPreview}<div class="notice"><div><strong>索引整理预览</strong><p>历史 {cleanupPreview.history_before} → {cleanupPreview.history_after} 条；素材索引 {cleanupPreview.assets_before} → {cleanupPreview.assets_after} 条。候选文件预计 {Math.ceil(cleanupPreview.candidate_bytes/1024)} KiB。</p><p>{cleanupPreview.message}</p><details class="maintenance-list"><summary>查看具体历史与素材</summary><h3>保留历史</h3><ul>{#each cleanupPreview.retained_history as item}<li>{item}</li>{/each}</ul><h3>移除历史</h3><ul>{#each cleanupPreview.removed_history_records as item}<li>{item}</li>{/each}</ul><h3>素材保留原因</h3><ul>{#each cleanupPreview.protected_assets as item}<li><code>{item}</code></li>{/each}</ul><h3>候选回收文件</h3><ul>{#each cleanupPreview.candidate_assets as item}<li><code>{item}</code></li>{/each}</ul></details>{#if cleanupPreview.replaces_checkpoint}<p>确认后会替换上一次整理的撤销记录。</p>{/if}{#if cleanupPreview.release_resolution}<p>确认后释放上次发布处理记录槽，版本水位保留。</p>{/if}{#if cleanupPreview.pending_blocks_commit}<p>存在未完成发布。请先处理，再重新预览。</p>{/if}<div class="button-row"><button class="outline" disabled={!!busy} onclick={clearMaintenance}>取消</button><button class="primary" disabled={!!busy||fixture||cleanupPreview.pending_blocks_commit} onclick={confirmCleanup}>确认整理索引</button></div></div></div>{/if}
{#if gcPreview}<div class="notice"><div><strong>本批文件回收预览</strong><p>可删除 {gcPreview.eligible.length} 个，合计 {Math.ceil(gcPreview.eligible_bytes/1024)} KiB；已不存在 {gcPreview.already_missing.length} 个；需保留 {gcPreview.blocked.length} 个；新增引用 {gcPreview.referenced.length} 个。</p><p>{gcPreview.message}</p><details class="maintenance-list"><summary>查看保留与缺失文件</summary><h3>校验保留</h3><ul>{#each gcPreview.blocked_details as item}<li><code>{item}</code></li>{/each}</ul><h3>新增引用保留</h3><ul>{#each gcPreview.referenced as hash}<li><code>{hash}</code></li>{/each}</ul><h3>已不存在</h3><ul>{#each gcPreview.already_missing as hash}<li><code>{hash}</code></li>{/each}</ul></details><p>确认后删除可回收文件，并结束本批回收。其余文件保留，以后不会自动删除。本批完整撤销能力将结束。</p>{#if gcPreview.eligible.length}<details class="maintenance-list"><summary>查看待删除文件标识</summary><ul>{#each gcPreview.eligible as hash}<li><code>{hash}</code></li>{/each}</ul></details>{/if}{#if gcPreview.pending_blocks_commit}<p>存在未完成发布。请先处理，再重新预览。</p>{/if}<div class="button-row"><button class="outline" disabled={!!busy} onclick={clearMaintenance}>取消</button><button class="primary" disabled={!!busy||fixture||gcPreview.pending_blocks_commit} onclick={confirmGc}>确认回收并结束本批</button></div></div></div>{/if}
{#if maintenanceOutcome}<div class="notice"><div><p>{maintenanceOutcome.message}</p>{#if maintenanceOutcome.recovery}<p>{maintenanceOutcome.recovery}</p>{/if}</div></div>{/if}</section>
<section class="panel"><h2>加密备份与恢复</h2><p class="muted">备份包含草稿、历史、素材索引、发布配置和加密密钥。恢复后，各发布目标先回读并核对版本，再补齐素材并发布。进行中的整理撤销记录不随备份迁移；恢复前须先结束本机回收批次。</p><label class="backup-password">备份口令<input type="password" autocomplete="new-password" bind:value={passphrase} minlength="12" placeholder="至少 12 个字符，仅用于本次加解密"/></label><div class="button-row"><button class="outline" disabled={!!busy||passphrase.length<12||fixture} onclick={backup}>导出加密备份</button><button class="text-button" disabled={!!busy||recoveryHolding||fixture} onclick={()=>publisherAction('open_publisher_backup_folder','正在打开本机备份目录…',true)}>打开备份目录</button><label class="outline file-button" class:disabled={!!busy||recoveryHolding||fixture}>恢复加密备份<input type="file" accept=".json,.csbackup,application/json,application/octet-stream" disabled={!!busy||recoveryHolding||fixture} onchange={restoreBackup}/></label></div><div role="status" aria-live="polite">{#if backupOutcome}<div class="notice"><div><p>{backupOutcome.message}</p>{#if backupOutcome.recovery}<p>{backupOutcome.recovery}</p>{/if}</div></div>{/if}</div>{#if backupError}<div class="notice danger" role="alert"><Icon name="alert"/><p>{backupError}</p></div>{/if}</section>
{#if publishChannel}<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="publish-title" tabindex="-1" use:dialogFocus={()=>publishChannel=null}><h2 id="publish-title">发布到{publishChannel==='preview'?'预览渠道':'正式渠道'}</h2><p>此操作将广告清单、图片和签名写入该渠道已保存的发布来源。配置 R2 后会自动上传；未配置 R2 时使用本机目录。</p><p>{publishChannel==='preview'?'预览渠道不会改变正式广告区。':'远程正式内容供已固定对应域名和公钥的客户端读取。'}只有签名内容与素材回读通过，才视为发布完成。</p><div class="button-row"><button class="outline" onclick={()=>publishChannel=null}>取消</button><button class="primary" onclick={()=>publishChannel&&publish(publishChannel)}>确认发布</button></div></div></div>{/if}
</fieldset>
<style>
.recovery-guard{border:0;padding:0;margin:0;min-width:0}

.maintenance-list{max-width:100%;margin:12px 0}.maintenance-list h3{font-size:12px}.maintenance-list ul{max-height:220px;overflow:auto;padding-left:20px}.maintenance-list li{font-size:11px;margin:5px 0;overflow-wrap:anywhere}.maintenance-list code{font-size:10px;overflow-wrap:anywhere}

.slot-tabs{display:flex;border-bottom:1px solid var(--line);gap:6px;margin-bottom:18px}.slot-tabs button{flex:1;background:none;border:0;border-bottom:2px solid transparent;padding:12px 6px;color:var(--muted);font-size:12px}.slot-tabs button.chosen{color:var(--green);border-bottom-color:var(--green);font-weight:650}.editor-toolbar{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:5px 0 15px}.period-toolbar{display:flex;justify-content:space-between;align-items:center;gap:15px;margin:8px 0 22px}.period-button{border:1px solid var(--line);padding:8px 13px;border-radius:5px;background:transparent;color:var(--muted);font-size:12px}.period-button.chosen{color:var(--green);background:var(--tint);border-color:#b9cabc}.timezone-label{font-size:10px;color:var(--muted);display:flex;align-items:center;gap:8px}select,input,textarea{border:1px solid #ccd1c7;background:#fffefb;border-radius:4px;color:var(--ink);padding:9px 10px;min-width:0}select{font-size:11px;padding:7px}.editor-fields{display:grid;grid-template-columns:1fr 1fr;gap:17px}.editor-fields>label{display:flex;flex-direction:column;gap:7px;font-size:11px;font-weight:600}.editor-fields input,.editor-fields textarea{font-size:12px;font-weight:400;width:100%}.editor-fields .checkbox-label{white-space:nowrap}.editor-fields .checkbox-label input{width:17px;flex:0 0 17px}.editor-fields small{font-size:10px;font-weight:400;color:var(--muted)}.wide{grid-column:1/-1}.image-row{display:flex;align-items:center;justify-content:space-between;padding:15px;background:var(--tint);border-radius:5px;gap:15px}.image-row strong{font-size:12px}.image-row p{font-size:11px;color:var(--muted);margin:5px 0}.file-button{position:relative;overflow:hidden;white-space:nowrap;cursor:pointer}.file-button input{position:absolute;width:1px;height:1px;opacity:0}.file-button:focus-within{outline:3px solid #699d80;outline-offset:3px}.file-button.disabled{opacity:.48;cursor:default}.remove{color:#a14c3a}.preview-label{font-size:10px;color:var(--muted);margin:8px 0 13px}.preview-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px;max-width:844px}.preview-grid.compact{max-width:704px;gap:11px}.validation{background:#fbf0e1;border:1px solid #efcaa4;color:#a05a13;padding:13px 17px;border-radius:6px;font-size:11px;margin:15px 0}.validation ul{padding-left:18px;margin-bottom:0;line-height:1.7}.history-list>div{display:flex;align-items:center;justify-content:space-between;padding:14px 0;border-top:1px solid var(--line);gap:18px}.history-list strong{font-size:12px}.history-list small{display:block;font-size:10px;color:var(--muted);margin-top:6px}.empty-copy{font-size:12px;color:var(--muted);padding:15px;background:var(--tint);border-radius:5px}.backup-password{display:flex;flex-direction:column;gap:8px;max-width:420px;font-size:11px;margin:20px 0 15px}.backup-password input{font-size:12px}@media(max-width:1050px){.period-toolbar{align-items:flex-start;flex-direction:column}.preview-grid{gap:10px}.editor-fields{gap:13px}.image-row{flex-wrap:wrap}}
</style>
